CREATE TABLE intercom_recordings (id VARCHAR(36) PRIMARY KEY, space_id VARCHAR(36) NOT NULL REFERENCES collaboration_spaces(id) ON DELETE CASCADE, case_id VARCHAR(36) NOT NULL REFERENCES cases(id) ON DELETE CASCADE, user_id VARCHAR(36) NOT NULL REFERENCES users(id), object_key VARCHAR(500) NOT NULL UNIQUE, source_content_type VARCHAR(100) NOT NULL, final_content_type VARCHAR(100) NOT NULL, byte_size BIGINT NOT NULL CHECK (byte_size > 0), started_at VARCHAR(40) NOT NULL, ended_at VARCHAR(40) NOT NULL, transcription_status VARCHAR(20) NOT NULL CHECK (transcription_status IN ('queued','processing','completed','failed')), created_at VARCHAR(40) NOT NULL, failed_reason TEXT NULL);
-- statement-break
CREATE INDEX idx_intercom_recordings_space_created ON intercom_recordings(space_id, created_at);
